"""Artist-specific signals and the clean channel-analysis surface.
Counters use the existing 17 Nov capture; comments / metadata checked 18 Nov.
The two captures are explicit and never joined into a growth estimate.
"""
import json,re,html,collections,statistics

def revise(slides,old_analysis,D,out):
 S=json.loads((out/'signals-2026-11-18.json').read_text());V=D['videos'];by={v['id']:v for v in V};E=lambda s:html.escape(str(s),quote=True)
 def fmt(n):return f'{n/1e6:.2f}m' if n>=1e6 else f'{n/1e3:.1f}k' if n>=1000 else str(n)
 def cat(v):
  t=v['title'].lower()
  if not v['durationSec']:return 'Unavailable record'
  if v['isShort']:return 'Shorts¹'
  if 'conversation' in t:return 'Artist conversation'
  if 'home demo' in t:return 'Home demo'
  if 'live' in t and 'audio' in t:return 'Session audio'
  if 'live' in t or 'dscvr' in t:return 'Live performance video'
  if 'lyric' in t:return 'Lyric video'
  if 'visualiz' in t:return 'Visualizer'
  if 'music video' in t:return 'Music video'
  if 'audio' in t:return 'Official audio'
  return 'Other'
 def link(id,title=None):return f'<a href="https://www.youtube.com/watch?v={id}" target="_blank" rel="noopener">{E(title or by[id]["title"].replace("Blondshell - ",""))} ↗</a>'
 def photo(id,title=None,meta='',values=True):
  v=by[id];title=title or v['title'].replace('Blondshell - ','')
  val=f'<div class="value">{fmt(v["views"])} <small>lifetime views ↗</small></div>' if values else ''
  return f'<a class="photo" href="https://www.youtube.com/watch?v={id}" target="_blank" rel="noopener"><figure><img src="/blondshell/images/{id}.jpg" width="480" height="360" alt="{E(title)}" loading="eager"><figcaption>{val}<div class="title">{E(title)}</div><div class="meta">{E(meta)}</div></figcaption></figure></a>'
 def head(k,t):return f'<span class="label">{k}</span><h2>{t}</h2>'
 def note(t):return f'<p class="source">{t}</p>'
 def make(id,title,body):return f'<section class="slide" id="{id}" data-title="{E(title)}"><div class="inner">{body}</div><div class="folio"><span>Blondshell × YouTube · Partisan Records</span><span>00 / {E(title)}</span></div></section>'
 def quote(t,meta):return f'<blockquote>{E(t)}<cite>{E(meta)}</cite></blockquote>'
 replacements={}
 replacements['verdict']=make('verdict','The channel-specific readout',head('Three signals to build on','The next ideas are<br><span class="serif">already in her channel.</span>')+'''<div class="signal-readout signal-visual mt"><article><a class="signal-frame" href="https://www.youtube.com/watch?v=IBtqjLAXVPc" target="_blank" rel="noopener" aria-label="Watch the existing Olympus and Invincible Short"><img src="/blondshell/images/IBtqjLAXVPc.jpg" width="480" height="360" alt="The Invincible scene featured in Blondshell’s Olympus Short"><span class="signal-kind">01 / discovery · existing Short</span><span class="signal-open" aria-hidden="true"><svg viewBox="0 0 16 16" width="18" height="18" fill="none"><path d="M4 12 12 4M4 4h8v8" stroke="currentColor" stroke-width="1.3"/></svg></span></a><h3>Olympus × Invincible.</h3><div class="signal-proof"><b>55<span>/100</span></b><span>sampled Olympus comments<br>mention Invincible</span></div></article><article><a class="signal-frame" href="https://www.youtube.com/watch?v=v42NfgSoIuE" target="_blank" rel="noopener" aria-label="Listen to Arms featuring Gigi Perez"><img src="/blondshell/images/v42NfgSoIuE.jpg" width="480" height="360" alt="Arms featuring Gigi Perez official artwork with portraits of both artists"><span class="signal-kind">02 / alternate · official audio</span><span class="signal-open" aria-hidden="true"><svg viewBox="0 0 16 16" width="18" height="18" fill="none"><path d="M4 12 12 4M4 4h8v8" stroke="currentColor" stroke-width="1.3"/></svg></span></a><h3>Arms × Gigi Perez.</h3><div class="signal-proof"><b class="word">acoustic</b><span>requested in comments<br>alternate released 8 Oct 2025</span></div></article><article><a class="signal-frame" href="https://www.youtube.com/watch?v=m-AolGenrfg" target="_blank" rel="noopener" aria-label="Watch the Salad music video"><img src="/blondshell/images/m-AolGenrfg.jpg" width="480" height="360" alt="Blondshell performing beside a rocky stream in the Salad music video"><span class="signal-kind">03 / artist access · Premiere</span><span class="signal-open" aria-hidden="true"><svg viewBox="0 0 16 16" width="18" height="18" fill="none"><path d="M4 12 12 4M4 4h8v8" stroke="currentColor" stroke-width="1.3"/></svg></span></a><h3>Before Salad.</h3><div class="signal-proof"><b>30 <span>min</span></b><span>producer conversation →<br>Salad video Premiere</span></div></article></div><p class="takeaway"><b>For Violins:</b> back one song with a full performance, a stripped take or a lyric-led follow-up.</p>'''+note('API + sampled comments → INFERENCE. Olympus: 100 relevance-ranked comments, not a share of viewers. The Arms comments do not establish why the alternate was made; the Salad pairing does not prove a viewing uplift.'))

 replacements['catalogue']=make('catalogue','Olympus has a named discovery route',head('Catalogue discovery · Olympus','Fans tell us<br><span class="serif">how they found Olympus.</span>')+'<div class="grid2 mt"><div>'+photo('dk44JuEaTmc','Olympus · official audio','The retrieved catalogue leader')+'</div><div class="quotes">'+quote('Here from Invincible. Amazing song ❤','Olympus · sampled public comment · 2,141 likes')+'<p class="signal-number"><b>55 / 100</b><span>sampled Olympus comments mention Invincible</span></p><p class="takeaway">Keep that route alive: a song-led catalogue Short or playlist can welcome those viewers into Violins.</p></div></div>'+note('API + comment sample. 100 relevance-ranked comments, read 18 Nov; this is a selected sample, not 55% of all viewers. The channel’s existing Invincible Short holds 48.7k lifetime views. Discovery timing and traffic attribution require Studio.'))
 replacements['audience']=make('audience','Fans already recognise the acoustic alternative',head('Acoustic · an existing fan signal','They asked for acoustic Arms.<br><span class="serif">They recognised the answer.</span>')+'<div class="grid2 mt"><div>'+photo('v42NfgSoIuE','Arms feat. Gigi Perez','Acoustic guitar-led alternate · 8 Oct 2025')+'</div><div class="quotes">'+quote('this would be fantastic as an acoustic version!','Arms original audio · 10 May 2025 · 11 likes')+quote('I begged for an acoustic version of Arms since the album dropped','Arms feat. Gigi Perez · 9 Oct 2025 · 12 likes')+'<p class="takeaway">Test one stripped Violins performance. Choose the song with the artist and check existing takes before booking a shoot.</p></div></div>'+note('API + sampled comments → inference. Acoustic arrangement supported by the upload’s instrument credits. Requests are individual comments, not a demand census; they do not establish why the alternate version was made. Acoustic content already exists.'))
 replacements['live']=make('live','The live precedent is the duet',head('Live performance · the Docket precedent','The second version<br><span class="serif">lets the voices meet.</span>')+'<div class="grid2 mt"><div>'+photo('zzZiTQ20EFc','Docket feat. Bully · Saturn Sound','Full performance · 26 Jun 2024')+'</div><div class="quotes">'+quote('If the two of you did an entire album together it would probably be incredible.','Docket live · sampled public comment · 279 likes')+'<p class="lead">The duet is what this audience explicitly responds to. Toy and Thumbtack also have full Vevo performances.</p><p class="takeaway">For the current record, first investigate the full XMU takes behind the Heart Has To Work and Stone Fruit Shorts.</p></div></div>'+note('API + sampled comments → inference. Three retrieved full performance videos; Diet Pepsi is separately a session audio. A KEXP full session exists on the partner channel and is excluded from these counts. No live-versus-studio efficiency claim or new collaboration is assumed.'))
 replacements['premieres']=make('premieres','Premieres and artist access have precedent',head('Premieres · one particularly useful precedent','Before Salad,<br><span class="serif">the artist and producer showed up.</span>')+'<div class="premiere-sequence mt"><article>'+photo('nIXwigX5lTY','Blondshell & Yves Rothman','16 May 2023 · actual start 16:30 UTC · 31-minute conversation',False)+'<span class="sequence-time">16:30</span><h3>Inside the record.</h3></article><span class="sequence-arrow" aria-hidden="true">→</span><article>'+photo('m-AolGenrfg','Salad · music video','16 May 2023 · actual start 17:00 UTC',False)+'<span class="sequence-time">17:00</span><h3>Into the video.</h3></article></div><div class="weekly-strip"><span><b>4 music videos</b> have confirmed Premiere metadata: Joiner, Salad, T&amp;A, Event of a Fire</span></div><p class="scene-read">Bring a brief artist moment to a major video when she can participate. Keep it selective; a long conversation is a core-fan extra, not the reach benchmark.</p>'+note('API. Both scheduled and actual starts present for those four official videos. The conversation description explicitly invites a livestream followed by Salad. Its publication date is 17 May, but the broadcast began on 16 May. Current Violins anchors have no retained broadcast details: unknown, not proof they never premiered. No causal uplift claimed.'))
 replacements['formats']=make('formats','Give Shorts a song to lead towards',head('Shorts · specific routes into Blondshell','Keep the personality.<br><span class="serif">Make the musical destination obvious.</span>')+'<div class="grid3 mt">'+photo('IBtqjLAXVPc','Olympus in Invincible','A clear discovery hook · 29 Nov 2023')+photo('6FXzBwYaeM0','Sirius XMU session announcement','A named full-session destination')+photo('0wGC3JLV92E','Heart Has To Work on Sirius XM','A current performance excerpt')+'</div><p class="takeaway">Use a recognisable song, a compelling lyric or a real performance moment; link each chosen Short to the relevant full song.</p>'+note('API → inference. These examples have different ages and roles, so they are not a creative ranking. The biggest lifetime Short is a personality/festival post; humour does not need removing. Short Related Video configuration and actual click-through are not public. 465 duration-proxy Shorts across the retrieved channel.'))
 replacements['priorities']=make('priorities','Three specific moves for Violins',head('What Partisan should prioritise','Back one song.<br><span class="serif">Give it another reason to watch.</span>')+'''<div class="grid3 mt"><article class="decision"><span class="n">01 / Performance</span><h3>Finish the<br>XMU journey.</h3><p>Stone Fruit and Heart Has To Work already have excerpts. Ask which full takes are cleared for the artist channel.</p><div class="note"><b>Existing:</b> public excerpts<br><b>Needs:</b> full recording, rights and edit approval</div></article><article class="decision"><span class="n">02 / Acoustic test</span><h3>One stripped<br>Violins take.</h3><p>Arms gives a real precedent for alternate arrangements. Select the current song with the artist; trial one before promising a series.</p><div class="note"><b>Evidence:</b> Arms comments + acoustic alternate<br><b>Needs:</b> an approved take or new filming</div></article><article class="decision"><span class="n">03 / Words &amp; visuals</span><h3>A lyric route<br>into Violins.</h3><p>The title track has a music video, with no separate full lyric version identified. Salad and What’s Fair show an existing lyric-video audience.</p><div class="note"><b>Existing:</b> song, video world and lyric precedent<br><b>Needs:</b> approved text, creative edit and channel access</div></article></div>'''+note('Recommendations, not booked deliverables. One sampled Violins comment asks about the chorus words; that is a useful prompt, not broad demand. Existing partner material should be curated or licensed before duplicate uploads or new production.'))
 replacements['roadmap']=make('roadmap','A focused post-album programme',head('Proposed next four weeks','Choose the next version.<br><span class="serif">Build the support around it.</span>')+'''<div class="programme mt"><div class="programme-row"><b>01</b><b>18–24 Nov · choose &amp; clear</b><p>Label / management confirms XMU takes and permissions. Pick Stone Fruit or Heart Has To Work if a full performance is usable.</p></div><div class="programme-row"><b>02</b><b>25 Nov–1 Dec · set up the song</b><p>One specific story or performance Short. Connect the existing full song and add partner sessions to a clear live/alternate route.</p></div><div class="programme-row"><b>03</b><b>2–8 Dec · the second destination</b><p>Publish the cleared full take. If unavailable, choose a lyric edit or obtain approval for a stripped performance; do not assume all three.</p></div><div class="programme-row"><b>04</b><b>9–15 Dec · read &amp; extend</b><p>Review day-7 response in Studio, then a day-28 read. Release one distinct supporting Short; decide on a second performance from the evidence.</p></div></div><p class="takeaway">For the next major music video: consider a short artist-led Premiere moment, using the Salad precedent.</p>'''+note('INFERENCE. Proposed timings depend on asset clearance, artist time and edit capacity. Measure matched-age views plus authorised retention and traffic paths. Public comments and counters do not predict a guaranteed audience or budget return.'))
 from blondshell_post_album import programme
 replacements.update(programme(out,make,head,note))
 # Existing data-led album slides remain; remove the generic next-campaign slide.
 orig={re.search(r' id="([^"]+)"',s).group(1):s for s in slides}
 orig.update(replacements);orig.pop('next-campaign',None)
 orig['intro']=orig['intro'].replace('Released 25 September 2026 · a day-53 reading.','Released 25 September 2026 · campaign review through day 53.<br>Channel signals and fan research checked 18 November.')
 orig['method']=orig['method'].replace('Titles, dates, duration, public counters, playlists and sampled comments.','Titles, dates, duration, public counters, playlists and Premiere metadata.').replace('Source notes and complete window inventories are available in Analysis.','Fan research: 2,076 sampled comments across 62 uploads, checked 18 Nov. Source notes and complete inventories are in Analysis.')
 from blondshell_editorial import edit
 order=edit(orig,by,make,head,fmt)
 revised=[]
 for n,id in enumerate(order,1):
  s=orig[id];s=re.sub(r'(<div class="folio"><span>.*?</span><span>)\d\d /',lambda m:m.group(1)+f'{n:02d} /',s,flags=re.S);revised.append(s)
 # A clean, open analysis page: short tables first; long inventories stay optional.
 groups=collections.defaultdict(list)
 for v in V:groups[cat(v)].append(v)
 assert len(groups['Music video'])==9 and len(groups['Lyric video'])==9 and len(groups['Shorts¹'])==465 and len(groups['Live performance video'])==3
 assert sum(len(v) for v in groups.values())==520
 assert S['commentScan']['videos']==62 and S['commentScan']['comments']==2076 and S['commentScan']['olympusInvincibleMentions']==55
 signal_read={
 'Music video':('Salad · 344.7k; T&A · 330.6k','Keep the visual world; a selective Premiere can add participation.'),
 'Lyric video':('Salad · 279.7k; What’s Fair · 276.0k','A lyric-led current-song test has channel precedent.'),
 'Visualizer':('Docket · 252.3k','A primary song destination; do not assume an MV is required.'),
 'Live performance video':('Docket · 144.7k; Toy & Thumbtack · Vevo','Finish a current full-session journey if rights allow.'),
 'Session audio':('Diet Pepsi · 71.8k','A cover/session recording already found listeners.'),
 'Official audio':('Olympus · 671.0k; Arms alternate · 28.9k','Retain catalogue routes and album coverage.'),
 'Shorts¹':('Invincible / Olympus · 48.7k; XMU announcement · 18.3k','Keep personality; give song Shorts a named destination.'),
 'Home demo':('Kiss City home demo · 7.4k','One example, not a proven series.'),
 'Artist conversation':('Yves Rothman conversation · 1.5k','Core-fan access around a release, not a reach target.')}
 fmtrows=[]
 for k in signal_read:
  a=groups[k];sig,act=signal_read[k];fmtrows.append(f'<tr><th scope="row">{k}</th><td class="n">{len(a)}</td><td class="n">{fmt(sum(v["views"] for v in a))}</td><td>{sig}</td><td>{act}</td></tr>')
 def cell(id,label='Found'):
  return f'<a class="found" href="https://www.youtube.com/watch?v={id}" target="_blank" rel="noopener">{label} ↗</a>' if id else '<span class="not-found">Not identified</span>'
 matrix=[('Olympus',None,None,'dk44JuEaTmc',None,None),('Salad','m-AolGenrfg','wbu4mZmdAFY',None,None,None),('Docket',None,None,'if2juwy6T70','zzZiTQ20EFc',None),('Arms',None,None,'CSJF-hjQWOM',None,'v42NfgSoIuE'),('T&A','0Zy1_ZbBbJg',None,'zkaLvuyMlY4',None,'wgEy8C-Hlj8'),('Heart Has To Work',None,None,'5qX3xsr5zlQ',None,None),('Violins','ytdwKm-dJyg',None,None,None,None),('Fur Elise',None,'m1pJ3WNwlCo',None,None,None),('Stone Fruit','7M9A_sVI4BI',None,None,None,None)]
 matrixrows=[]
 for name,mv,lyric,audio,live,acoustic in matrix:
  matrixrows.append(f'<tr><th scope="row">{name}</th><td>{cell(mv)}</td><td>{cell(lyric)}</td><td>{cell(audio,"Audio / visual")}</td><td>{cell(live,"Full performance")}</td><td>{cell(acoustic,"Short excerpt" if acoustic=="wgEy8C-Hlj8" else "Acoustic alternate")}</td></tr>')
 def section(id,title,body):return f'<section class="audit-section" id="{id}"><h3>{title}</h3>{body}</section>'
 def t(heads,rows,cls=''):return '<div class="table-wrap"><table class="audit-table '+cls+'"><thead><tr>'+''.join('<th>'+E(h)+'</th>' for h in heads)+'</tr></thead><tbody>'+''.join(rows)+'</tbody></table></div>'
 def row(a,b,c=''):return f'<tr><th scope="row">{a}</th><td>{b}</td>'+ (f'<td>{c}</td>' if c else '')+'</tr>'
 overview=t(['Channel at capture','Public evidence','Read'],[
 row('Public subscribers','18,800','Rounded public count; not unique fans.'),row('Retrieved catalogue','520 rows · uncapped','519 playable entries; one zero-duration record.'),row('Channel vs retrieved views','8.52m / 6.29m','Scopes differ by 2.23m; no whole-channel share claim.'),row('Latest upload','7 Nov 2026','Most recent 30-day window: 14 Shorts, no full-song upload.'),row('Violins album coverage','11 / 11 songs','Primary full-song destinations all available by release day.'),row('Full follow-up after release','0 new full-song album versions','24 Shorts in days +1–53, in this retrieved channel.'),row('Public playlists','5 · Violins playlist (11 items) created 25 Sep','No public live/session playlist returned. End screens and Related Videos need Studio.')])
 register=t(['Surface','What exists','What it tells us'],[
 row('Premieres','4 official videos with scheduled + actual starts','Joiner, Salad, T&A, Event of a Fire. Current metadata absent means unknown.'),row('Acoustic / stripped','Arms feat. Gigi Perez; BBC T&A and Berlin acoustic excerpts','Acoustic is already part of her work; do not call it a missing format.'),row('Live performances','Docket; Toy; Thumbtack; a partner KEXP session','Three owned-channel full videos. Partner viewing is outside the counts.'),row('Fan requests','Arms acoustic request; Docket collaboration request','Useful individual signals; not a survey or forecast.'),row('Song discovery','55 of 100 sampled Olympus comments mention Invincible','Relevance-ranked sample, not a share of viewers or attributed traffic.')])
 songintro='<p>Selected songs and the versions identified on the artist channel. Links open real assets. An absent cell is an inventory gap here, not a production brief or proof a version was never made.</p>'
