 fanrows=[row('Olympus / discovery','55 of 100 sampled comments name Invincible; the highest-liked example has 2,141 likes.','Use catalogue recognition as an entry route; do not infer traffic share.'),row('Arms / acoustic','10 May 2025: an acoustic request on the original. 9 Oct: a comment on the Gigi version recognises that treatment.','An existing alternate is answering a recognisable fan interest; causation is unknown.'),row('Docket / collaboration','The live performance’s leading sampled request asks for a whole record together (279 likes).','Paired voices are a specific creative signal; a new collaboration needs artist agreement.'),row('Violins / words','One sampled viewer asks about the chorus lyrics. Salad and What’s Fair are strong lyric-video precedents.','A lyric asset is a reasonable test, not evidence of mass unmet demand.'),row('Current visuals','A Stone Fruit comment notices recurring obscured-vision imagery (30 likes).','Carry the album’s visual identity into future versions.')]
 premiere_rows=[]
 for v in S['broadcasts']:
  if v['actualStart'] and v['scheduledStart']:
   premiere_rows.append(row(link(v['id']),v['scheduledStart'].replace('T',' ').replace('Z',' UTC'),v['actualStart'].replace('T',' ').replace('Z',' UTC')))
 premieretable=t(['Asset','Scheduled start','Actual start'],premiere_rows)
 notes='''<p><b>Capture dates.</b> Catalogue counters and album review remain at 17 Nov 2026. Broadcast metadata, arrangement credits and comments were checked 18 Nov. No one-day growth is inferred from the two captures.</p><p><b>Views.</b> Lifetime counters at capture, not views earned in historical campaign windows. No paid/organic split, CTR, retention, unique viewers or conversion is available. Cross-format and cross-era figures are descriptive; age, spend and selection differ.</p><p><b>Shorts¹.</b> Existing API proxy: duration &gt;0 and ≤62 seconds. Not verified Shorts-feed status; longer Shorts may be missed.</p><p><b>Watcher.</b> 22 channel observations from 27 Oct; repeated counters and no release-week or previous-album baseline. No current growth-rate claim. Stone Fruit has a usable limited observed interval, not evidence it is the fastest current song.</p><p><b>Premieres.</b> The app identifies a Premiere from scheduled and actual starts on an official music video. Both establish an aired broadcast; missing retained metadata is unknown. The producer conversation is a separate livestream, supported by its description. Its actual start is 16 May even though its publication date is 17 May.</p><p><b>Comments.</b> 2,076 relevance-ranked top-level comments across 62 selected uploads (54 full-length and eight highest-viewed Shorts), max 100 each. This is not all commenters or a representative audience. Quotes and like counts are recorded in the signals file; no sentiment score or inferred demand total is used.</p><p><b>Partner footage.</b> KEXP full performance is linked on the partner channel: <a href="https://www.youtube.com/watch?v=oMufqxs64bw" target="_blank" rel="noopener">watch the session ↗</a>. BBC and Berlin examples are artist-channel excerpts. Availability of full takes, rights and permission to duplicate partner uploads must be checked.</p>'''
 inventory=''.join(re.findall(r'<details><summary>(?:Confirmed Violins|Complete current|Previous album:|Catalogue:).*?</details>',old_analysis,re.S))
 analysis='''<section id="analysis" class="analysis-sheet" role="dialog" aria-modal="true" aria-labelledby="analysis-title" tabindex="-1" hidden><header class="analysis-toolbar"><a class="brand" href="#analysis">Blondshell · channel analysis</a><button id="close-analysis" type="button" aria-label="Close analysis">Close ×</button></header><div class="analysis-sheet-inner analysis-content appendix clean-analysis"><span class="label">Channel evidence · catalogue 17 Nov / signals checked 18 Nov 2026</span><h2 id="analysis-title">What’s on the channel.<br><span class="serif">What to build on.</span></h2><p class="audit-intro">Music videos, acoustic versions, live performances, Shorts and the fan signals behind the recommendations.</p><nav class="audit-nav" aria-label="Analysis sections"><a href="#signal-overview">At a glance</a><a href="#format-audit">Formats</a><a href="#song-audit">Songs &amp; versions</a><a href="#fan-audit">Fan signals</a><a href="#premiere-audit">Premieres</a><a href="#evidence-notes">Sources</a></nav>'''
