 analysis+=section('evidence-notes','Sources and measurement',notes+'<p><b>Post-album proposal.</b> Eight weeks, 23 Nov–17 Jan: 16 proposed Shorts, one proposed full performance and one optional second full-length version. Asset delivery and approval are unconfirmed; no view forecast is made. <a href="/blondshell/post-album-plan.json" target="_blank" rel="noopener">Read the proposed schedule ↗</a>.</p>'+'<div class="actions"><a class="button" href="/blondshell/signals-2026-11-18.json" target="_blank">Signal evidence ↗</a><a class="button secondary" href="/blondshell/research-2026-11-17.json" target="_blank">Catalogue rows ↗</a><a class="button secondary" href="/blondshell/calculations-2026-11-17.json" target="_blank">Campaign calculations ↗</a></div><h4>Complete inventories</h4>'+inventory)
